// Compares the freshly fetched label text against the last known version
// stored in workflow static data (per product). No external DB needed.
const cfg = $('Prepare Configurations').first().json;
const response = $input.first().json;
const newLabelText = response.labelText || response.text || JSON.stringify(response);

const staticData = $getWorkflowStaticData('node');
if (!staticData.labelsByProduct) staticData.labelsByProduct = {};

const previous = staticData.labelsByProduct[cfg.productId];
const previousLabelText = previous ? previous.labelText : null;
const labelChanged = previousLabelText !== null && previousLabelText !== newLabelText;
const isFirstSeen = previousLabelText === null;

return [{
  json: {
    ...cfg,
    newLabelText,
    previousLabelText: previousLabelText || '',
    labelChanged: labelChanged || isFirstSeen,
    isFirstSeen,
    checkedAt: new Date().toISOString()
  }
}];

const labelState = $('If Label Has Changed').first().json;
const productData = $input.first().json;

return [{
  json: {
    ...labelState,
    affectedProcesses: productData.processes || productData.affectedProcesses || [],
    affectedBatches: productData.batches || productData.affectedBatches || [],
    productLine: productData.productLine || productData.line || '',
    manufacturingSites: productData.manufacturingSites || productData.sites || []
  }
}];

