const upstream = $('Merge Label and Product Data').first().json;
const response = $input.first().json;

let parsed = {
  changeSummary: '',
  changedSections: [],
  severity: 'Major',
  severityReasoning: 'AI analysis unavailable this cycle; defaulted to Major for manual review.',
  requiredActionsRegulatory: [],
  requiredActionsQuality: []
};
try {
  const raw = String(response.output || response.text || response.response || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  // keep safe default above
}

return [{
  json: {
    ...upstream,
    changeSummary: parsed.changeSummary || '',
    changedSections: parsed.changedSections || [],
    severity: parsed.severity || 'Major',
    severityReasoning: parsed.severityReasoning || '',
    requiredActionsRegulatory: parsed.requiredActionsRegulatory || [],
    requiredActionsQuality: parsed.requiredActionsQuality || []
  }
}];

