// Persist the new label text as the baseline for next cycle's diff,
// scoped per product in workflow static data.
const item = $input.first().json;
const staticData = $getWorkflowStaticData('node');
if (!staticData.labelsByProduct) staticData.labelsByProduct = {};

staticData.labelsByProduct[item.productId] = {
  labelText: item.newLabelText,
  updatedAt: new Date().toISOString(),
  lastSeverity: item.severity
};

return [{ json: { ...item, baselineUpdated: true } }];
